int n_rescue[N][N] = {};
int infect_time[N][N] = {};
int di[] = {-1, 1, 0, 0};
int dj[] = {0, 0, -1, 1};
int reach_time[N][N][N][N] = {};
const int FLOW_N = 2 * N * N + 2;
const int INF = 1'000'000'000;
vector<int> adj[FLOW_N+1];
int c[FLOW_N+1][FLOW_N+1], f[FLOW_N+1][FLOW_N+1], adj_ptr[FLOW_N+1], d[FLOW_N+1], p[FLOW_N+1];

bool build_level_graph(int s, int t) {
    memset(d, -1, sizeof d);
    d[s] = 0;
    queue<int> q;
    q.push(s);
    while(!q.empty()) {
        int u = q.front(); q.pop();
        for(int v : adj[u]) {
            if(c[u][v] - f[u][v] > 0 && d[v] == -1) {
                d[v] = d[u] + 1;
                q.push(v);
            }
        }
    }
    return d[t] != -1;
}

bool dfs_path(int u, int t) {
    if(u == t) return true;
    for(int& i = adj_ptr[u]; i < (int)adj[u].size(); i++) {
        int v = adj[u][i];
        if(d[v] == d[u] + 1 && c[u][v] - f[u][v] > 0 && dfs_path(v, t)) {
            p[v] = u;
            return true;
        }
    }
    return false;
}

bool find_augmenting_path(int s, int t) {
    memset(p, -1, sizeof p);
    p[s] = 0;
    return dfs_path(s, t);
}

void initialize_flow() {
    memset(c, 0, sizeof c);
    memset(f, 0, sizeof f);
}

void add_edge(int u, int v, int cap) {
    adj[u].push_back(v);
    adj[v].push_back(u);
    c[u][v] += cap;
}

int compute_max_flow(int s, int t) {
    int total_flow = 0;
    while(build_level_graph(s, t)) {
        memset(adj_ptr, 0, sizeof adj_ptr);
        while(find_augmenting_path(s, t)) {
            int flow_cap = INF;
            for(int v = t, u = p[v]; v != s; v = u, u = p[v]) {
                flow_cap = min(flow_cap, c[u][v] - f[u][v]);
