            for(int v = t, u = p[v]; v != s; v = u, u = p[v]) {
                f[u][v] += flow_cap;
                f[v][u] -= flow_cap;
            }
            total_flow += flow_cap;
        }
    }
    return total_flow;
}

int node_id(int n, int i, int j, bool right) {
