import java.util.*;
import java.io.*;

public class Main {
    static final int N = 10;
    static String[] g = new String[N];
    static int[][] n_scientists = new int[N][N];
    static int[][] n_rescue = new int[N][N];
    static int[][] infect_time = new int[N][N];
    static int[][][] reach_time = new int[N][N][N][N];
    static int[] di = {-1, 1, 0, 0};
    static int[] dj = {0, 0, -1, 1};
    static final int FLOW_N = 2 * N * N + 2;
    static final int INF = 1000000000;
    static List<Integer>[] adj = new ArrayList[FLOW_N + 1];
    static int[][] c = new int[FLOW_N + 1][FLOW_N + 1];
    static int[][] f = new int[FLOW_N + 1][FLOW_N + 1];
    static int[] adj_ptr = new int[FLOW_N + 1];
    static int[] d = new int[FLOW_N + 1];
    static int[] p = new int[FLOW_N + 1];

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        for (int i = 0; i <= FLOW_N; i++) {
            adj[i] = new ArrayList<>();
        }

        String line = br.readLine();
        st = new StringTokenizer(line);
        int n = Integer.parseInt(st.nextToken());
        int t = Integer.parseInt(st.nextToken());

        int explosionX = -1, explosionY = -1;

        for (int i = 0; i < n; i++) {
            g[i] = br.readLine();
        }

        for (int i = 0; i < n; i++) {
            String row = g[i];
            for (int j = 0; j < n; j++) {
                char ch = row.charAt(j);
                if (ch == 'Y') {
                    // do nothing, g[i][j] = 'Y'
                } else if (ch == 'Z') {
                    explosionX = i;
                    explosionY = j;
                } else {
                    n_scientists[i][j] += ch - '0';
                }
            }
        }

        for (int i = 0; i < n; i++) {
            String line2 = br.readLine();
            for (int j = 0; j < n; j++) {
                char ch = line2.charAt(j);
                if (ch != 'Y' && ch != 'Z') {
                    n_rescue[i][j] += ch - '0';
                }
            }
        }

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                Arrays.fill(infect_time[i][j], -1);
            }
        }

        infect_time[explosionX][explosionY] = 0;
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{explosionX, explosionY});
        while (!q.isEmpty()) {
            int[] cell = q.poll();
            int i = cell[0], j = cell[1];
            for (int d = 0; d < 4; d++) {
                int ni = i + di[d], nj = j + dj[d];
                if (0 <= ni && ni < n && 0 <= nj && nj < n && g[ni].charAt(nj) == '.' && infect_time[ni][nj] == -1) {
                    infect_time[ni][nj] = infect_time[i][j] + 1;
                    q.offer(new int[]{ni, nj});
                }
            }
        }

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                for (int ii = 0; ii < N; ii++) {
                    Arrays.fill(reach_time[i][j][ii], -1);
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (g[i].charAt(j) == '.') {
                    reach_time[i][j][i][j] = 0;
                    Queue<int[]> q2 = new LinkedList<>();
                    q2.offer(new int[]{i, j});
                    while (!q2.isEmpty()) {
                        int[] cell2 = q2.poll();
                        int ii = cell2[0], jj = cell2[1];
                        if (infect_time[ii][jj] == -1 || reach_time[i][j][ii][jj] < infect_time[ii][jj]) {
                            for (int d = 0; d < 4; d++) {
                                int ni = ii + di[d], nj = jj + dj[d];
                                if (0 <= ni && ni < n && 0 <= nj && nj < n && g[ni].charAt(nj) == '.') &&
                                   (infect_time[ni][nj] == -1 || reach_time[i][j][ii][jj] + 1 <= infect_time[ni][nj]) &&
                                   reach_time[i][j][ni][nj] == -1) {
                                    reach_time[i][j][ni][nj] = reach_time[i][j][ii][jj] + 1;
                                    q2.offer(new int[]{ni, nj});
                                }
                            }
                        }
                    }
                }
            }
        }

        int src = 2 * n * n;
        int sink = 2 * n * n + 1;

        initializeFlow();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (n_scientists[i][j] > 0) {
                    addEdge(src, node_id(n, i, j, false), n_scientists[i][j]);
                }
                if (n_rescue[i][j] > 0) {
                    addEdge(node_id(n, i, j, true), sink, n_rescue[i][j]);
                }
                for (int ii = 0; ii < n; ii++) {
                    for (int jj = 0; jj < n; jj++) {
                        if (reach_time[i][j][ii][jj] != -1 && reach_time[i][j][ii][jj] <= t) {
                            addEdge(node_id(n, i, j, false), node_id(n, ii, jj, true), INF);
                        }
                    }
                }
            }
        }

        System.out.println(computeMaxFlow(src, sink));
    }

    static int node_id(int n, int i, int j, boolean right) {
        return i * n + j + (right ? n * n : 0);
    }

    static void initializeFlow() {
        for (int i = 0; i <= FLOW_N; i++) {
            Arrays.fill(c[i], 0);
            Arrays.fill(f[i], 0);
            adj[i].clear();
        }
        Arrays.fill(adj_ptr, 0);
    }

    static void addEdge(int u, int v, int cap) {
        adj[u].add(v);
        adj[v].add(u);
        c[u][v] += cap;
    }

    static int computeMaxFlow(int s, int t) {
        int totalFlow = 0;
        while (buildLevelGraph(s, t)) {
            Arrays.fill(adj_ptr, 0);
            while (findAugmentingPath(s, t)) {
                int flowCap = INF;
                for (int v = t, u = p[v]; v != s; v = u, u = p[v]) {
                    flowCap = Math.min(flowCap, c[u][v] - f[u][v]);
                }
                for (int v = t, u = p[v]; v != s; v = u, u = p[v]) {
                    f[u][v] += flowCap;
                    f[v][u] -= flowCap;
                }
                totalFlow += flowCap;
            }
        }
        return totalFlow;
    }

    static boolean buildLevelGraph(int s, int t) {
        Arrays.fill(d, -1);
        d[s] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(s);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : adj[u]) {
                if (c[u][v] - f[u][v] > 0 && d[v] == -1) {
                    d[v] = d[u] + 1;
                    q.offer(v);
                }
            }
        }
        return d[t] != -1;
    }

    static boolean findAugmentingPath(int u, int t) {
        if (u == t) return true;
        for (int i = adj_ptr[u]; i < adj[u].size(); i++) {
            int v = adj[u].get(i);
            if (d[v] == d[u] + 1 && c[u][v] - f[u][v] > 0 && findAugmentingPath(v, t)) {
                p[v] = u;
                return true;
            }
            adj_ptr[u]++;
        }
        return false;
    }
}
